package main

import "fmt"

func main() {
	s := "héllo" // é is 2 bytes in UTF-8
	fmt.Println(len(s)) // BYTE length, not character count
	// s[0] = 'H' would not compile: strings are immutable
	b := []byte(s)
	b[0] = 'H'
	fmt.Println(string(b))
	// Output: 6
	// Héllo
}

