package main

import "fmt"

func reverse(s string) string {
	r := []rune(s)            // decode into code points so each char is one unit
	for i, j := 0, len(r)-1; i < j; i, j = i+1, j-1 {
		r[i], r[j] = r[j], r[i] // swap whole runes, never partial bytes
	}
	return string(r)          // re-encode back to UTF-8
}

func main() {
	fmt.Println(reverse("go世")) // 世og
}

