package solution

import "unicode"

func Solve(s string) int {
	count := 0
	for _, r := range s {            // range decodes UTF-8 rune by rune
		switch unicode.ToLower(r) {  // normalize case once
		case 'a', 'e', 'i', 'o', 'u':
			count++
		}
	}
	return count
}

