func IsPalindrome(s string) bool {
	r := []rune(s) // decode so each character is one comparable unit
	for i, j := 0, len(r)-1; i < j; i, j = i+1, j-1 {
		if r[i] != r[j] { // compare runes from both ends
			return false
		}
	}
	return true
}

func Truncate(s string, maxChars int) string {
	if maxChars <= 0 {
		return ""
	}
	count := 0
	for i := range s { // i is the byte index where each rune starts
		if count == maxChars {
			return s[:i] // cut on a rune boundary
		}
		count++
	}
	return s // fewer than maxChars characters: return as-is
}
